package fr.shenpulse.box;
import java.util.*;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;
public final class BoxBridge extends ShenPulseBox {
 private org.bukkit.scheduler.BukkitTask multiplierReset;
 @Override public void onEnable(){prepareArena();super.onEnable();getCommand("shenpulse_box").setExecutor((sender,command,label,args)->{if(sender instanceof Player){sender.sendMessage("Commande réservée à ShenPulse.");return true;}if(args.length==0)return false;if(args[0].equals("sync")){try{var manager=getCountdownManager();var count=manager.getClass().getDeclaredField("winCount");count.setAccessible(true);count.setInt(manager,Integer.parseInt(args[1]));var factor=manager.getClass().getDeclaredField("shenMultiplier");factor.setAccessible(true);factor.setInt(manager,Math.max(1,Integer.parseInt(args[2])));if(multiplierReset!=null)multiplierReset.cancel();int seconds=Integer.parseInt(args[3]);if(seconds>0)multiplierReset=Bukkit.getScheduler().runTaskLater(this,()->{try{factor.setInt(manager,1);}catch(Exception e){getLogger().warning("Multiplicateur non rétabli");}},seconds*20L);else factor.setInt(manager,1);return true;}catch(Exception e){sender.sendMessage("Synchronisation refusée");return false;}}Set<String> commands=Set.of("step1","step2","step3","step4","step5","reset","prison1","noprison1","prison2","noprison2","shenfill","fusee");if(!commands.contains(args[0]))return false;return Bukkit.dispatchCommand(Bukkit.getConsoleSender(),String.join(" ",args));});}
 private void prepareArena(){World w=Bukkit.getWorlds().get(0);w.setGameRule(GameRule.DO_MOB_SPAWNING,false);w.setSpawnLocation(0,15,-22);for(int x=-5;x<=5;x++)for(int z=-27;z<=-17;z++)for(int y=14;y<=31;y++){boolean wall=x==-5||x==5||z==-27||z==-17;w.getBlockAt(x,y,z).setType(y==14?Material.BEDROCK:wall?Material.TINTED_GLASS:Material.AIR,false);}for(int x=-1;x<=3;x++)for(int z=-9;z<=-5;z++)for(int y=36;y<=40;y++)w.getBlockAt(x,y,z).setType(y==36||y==40?Material.SMOOTH_QUARTZ:x==-1||x==3||z==-9||z==-5?Material.GLASS:Material.AIR,false);
 // Independent parkour arena: fixed jumps, the original moving platform and a quartz exit.
 for(int i=0;i<5;i++)platform(w,1000+i*3,60,1000,Material.IRON_BLOCK);for(int z=1004;z<=1013;z++)w.getBlockAt(1013,60,z).setType(Material.AIR,false);platform(w,1013,60,1016,Material.IRON_BLOCK);for(int z=1019,i=0;z<=1046;z+=3,i++)platform(w,1013-(i%5)*3,60,z,Material.IRON_BLOCK);platform(w,1002,60,1048,Material.GOLD_BLOCK);platform(w,1002,60,1051,Material.QUARTZ_BLOCK);}
 private void platform(World w,int x,int y,int z,Material material){w.getBlockAt(x,y,z).setType(material,false);}
}
